    },
    {
        name: "biddingToken",
        type: "function",
        stateMutability: "view",
        inputs: [],
        outputs: [{ name: "", type: "address" }],
    },
    {
        name: "placeBid",
        type: "function",
        stateMutability: "nonpayable",
        inputs: [
            { name: "round", type: "uint64" },
            { name: "expressLaneController", type: "address" },
