];

// ==================== STATUS ENUM ====================
const STATUS = {
    NOT_FOUND: "NOT_FOUND",
    L1_PENDING: "L1_PENDING",
    L1_CONFIRMED: "L1_CONFIRMED",
    L2_TICKET_CREATED: "L2_TICKET_CREATED",
    L2_REDEEMED: "L2_REDEEMED",
    L2_FAILED: "L2_FAILED",
    EXPIRED: "EXPIRED",
};

// ==================== MAIN ====================
async function detectL1ToL2Status() {
